-- Local candidate only; filename generated by the supported CLI migration new.
-- Personal saved/comparison choices extend an already classified, guarded table.
alter table public.levytate_employee_development_profiles
 add column saved_programme_ids jsonb not null default '[]' check(jsonb_typeof(saved_programme_ids)='array' and jsonb_array_length(saved_programme_ids)<=100),
 add column compared_programme_ids jsonb not null default '[]' check(jsonb_typeof(compared_programme_ids)='array' and jsonb_array_length(compared_programme_ids)<=3),
 add column discovery_revision integer not null default 0 check(discovery_revision>=0);

create function public.levytate_personal_programme_choices(p_actor uuid,p_command jsonb default null) returns jsonb
language plpgsql security definer set search_path=pg_catalog,public as $$
declare actor public.levytate_users%rowtype;person public.levytate_employees%rowtype;
 profile public.levytate_employee_development_profiles%rowtype;receipt public.levytate_audit_events%rowtype;
 action text;programme text;request_id uuid;expected integer;saved jsonb;compared jsonb;available jsonb;revision integer;result jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception using errcode='42501',message='Service role required';end if;
 if p_command is not null then
  if jsonb_typeof(p_command) is distinct from 'object' or not(p_command ?& array['action','programmeId','requestId','expectedRevision'])
    or exists(select 1 from jsonb_object_keys(p_command) k where not(k=any(array['action','programmeId','requestId','expectedRevision']))) then
   raise exception using errcode='PT422',message='Exact programme choice command required';end if;
  action:=p_command->>'action';programme:=p_command->>'programmeId';request_id:=(p_command->>'requestId')::uuid;expected:=(p_command->>'expectedRevision')::integer;
  if jsonb_typeof(p_command->'action') is distinct from 'string' or jsonb_typeof(p_command->'programmeId') is distinct from 'string' or jsonb_typeof(p_command->'requestId') is distinct from 'string'
    or action is null or action not in('save','unsave','compare','uncompare') or programme is null or length(btrim(programme)) not between 1 and 160
    or programme<>btrim(programme) or request_id is null or expected is null or expected<0
    or jsonb_typeof(p_command->'expectedRevision') is distinct from 'number' or (p_command->>'expectedRevision')!~'^[0-9]+$' then
   raise exception using errcode='PT422',message='Valid bounded programme choice required';end if;
  perform pg_advisory_xact_lock(hashtextextended('programme-choice-request:'||request_id::text,0));
 end if;
 -- Same catalogue lock as publication/archive and application creation.
 perform pg_advisory_xact_lock(hashtextextended('levytate-catalogue-integrity',0));
 perform 1 from public.levytate_organisations where slug='levytate-internal' and status='Active' for share;
 select * into actor from public.levytate_users where id=p_actor and active and auth_binding_status='bound' and auth_subject is not null for share;
 if not found or actor.role not in('Employee','Line Manager') then raise exception using errcode='PT403',message='Personal development account required';end if;
 perform 1 from public.levytate_organisations where id=actor.organisation_id and status='Active' for share;
 if not found then raise exception using errcode='PT403',message='Active employer required';end if;
 if (select count(*) from public.levytate_employees where organisation_id=actor.organisation_id and status='Active' and lower(btrim(email))=lower(btrim(actor.email)) and platform_role=actor.role)<>1 then
  raise exception using errcode='PT403',message='Exactly one current personal record required';end if;
 select * into person from public.levytate_employees where organisation_id=actor.organisation_id and status='Active' and lower(btrim(email))=lower(btrim(actor.email)) and platform_role=actor.role for update;
 select * into profile from public.levytate_employee_development_profiles where organisation_id=actor.organisation_id and employee_id=person.id for update;
 saved:=coalesce(profile.saved_programme_ids,'[]');compared:=coalesce(profile.compared_programme_ids,'[]');revision:=coalesce(profile.discovery_revision,0);
 select coalesce(jsonb_agg(distinct p.id),'[]') into available from public.levytate_organisation_programmes s
   join public.levytate_provider_programmes p on p.id=s.programme_id and p.provider_id=s.provider_id
   join public.levytate_organisations catalog on catalog.id=p.organisation_id and catalog.slug='levytate-internal' and catalog.status='Active'
   join public.levytate_providers provider on provider.organisation_id=p.organisation_id and provider.provider_id=p.provider_id and provider.status='Active' and provider.verification_status='verified' and provider.last_verified is not null and jsonb_array_length(provider.source_urls)>0
   join public.levytate_organisation_providers r on r.organisation_id=s.organisation_id and r.provider_id=s.provider_id and r.status='Active'
   where s.organisation_id=actor.organisation_id and s.status='Active' and p.status='Active' and p.record_status='Active'
    and p.verification_status in('Verified from provider website','Provider confirmed','LevyTate reviewed') and nullif(btrim(p.source_url),'') is not null
    and jsonb_array_length(p.linked_standard_ids)>0 and not exists(select 1 from jsonb_array_elements_text(p.linked_standard_ids) standard_id where not exists(select 1 from public.levytate_apprenticeship_standards standard where standard.id=standard_id and standard.status='Approved for delivery'));
 if p_command is not null then
  select * into receipt from public.levytate_audit_events where id=request_id;
  if found then
   if receipt.organisation_id=actor.organisation_id and receipt.action='personal_programmes.changed'
    and receipt.metadata->>'actorId'=actor.id::text and receipt.metadata->'command'=p_command then return receipt.metadata->'result'||jsonb_build_object('availableProgrammeIds',available);end if;
   raise exception using errcode='PT409',message='Request key already used';end if;
  if revision<>expected then raise exception using errcode='PT409',message='Saved choices changed; inspect before editing';end if;
  if action in('save','compare') and not(available ? programme) then
   raise exception using errcode='PT422',message='Programme is not currently available from this employer';end if;
  if action='save' and not(saved ? programme) then saved:=saved||jsonb_build_array(programme);
  elsif action='unsave' then saved:=saved-programme;
  elsif action='compare' and not(compared ? programme) then compared:=compared||jsonb_build_array(programme);
  elsif action='uncompare' then compared:=compared-programme;end if;
  if jsonb_array_length(saved)>100 or jsonb_array_length(compared)>3 then raise exception using errcode='PT422',message='Save up to 100 programmes and compare up to 3';end if;
  revision:=revision+1;
  insert into public.levytate_employee_development_profiles(organisation_id,employee_id,stage,saved_programme_ids,compared_programme_ids,discovery_revision)
   values(actor.organisation_id,person.id,'role_context',saved,compared,revision)
   on conflict(organisation_id,employee_id) do update set saved_programme_ids=excluded.saved_programme_ids,compared_programme_ids=excluded.compared_programme_ids,
    discovery_revision=excluded.discovery_revision,updated_at=clock_timestamp();
 end if;
 result:=jsonb_build_object('employeeId',person.id,'savedProgrammeIds',saved,'comparedProgrammeIds',compared,'revision',revision);
 if p_command is not null then
  insert into public.levytate_audit_events(id,organisation_id,actor_email,actor_role,entity_type,entity_id,action,summary,metadata)
   values(request_id,actor.organisation_id,actor.email,actor.role,'personal_programmes',person.id,'personal_programmes.changed','Personal programme choices saved.',jsonb_build_object('actorId',actor.id,'command',p_command,'result',result));
 end if;
 return result||jsonb_build_object('availableProgrammeIds',available);
exception when invalid_text_representation or numeric_value_out_of_range then raise exception using errcode='PT422',message='Valid programme choice identifiers and revision required';
end; $$;
revoke all on function public.levytate_personal_programme_choices(uuid,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.levytate_personal_programme_choices(uuid,jsonb) to service_role;
